 "<b style=\"color:#fee440\">Lineal</b><br>suave de arriba abajo": "<b style=\"color:#fee440\">Linear</b><br>gleichmäßig von oben bis unten",
 "<b style=\"color:#f15bb5\">Táctil</b><br>un pequeño bache a mitad": "<b style=\"color:#f15bb5\">Taktil</b><br>kleiner Druckpunkt mittig",
